package com.vgc.controller.event.photoexhibition;
import com.vgc.dto.event.photoexhibition.PhotoExhibitionAdminSubmissionResponse; import com.vgc.dto.event.photoexhibition.PhotoExhibitionPreviewResponse; import com.vgc.dto.event.photoexhibition.PhotoExhibitionVoterAuditResponse; import com.vgc.entity.User; import com.vgc.repository.UserRepository; import com.vgc.service.event.photoexhibition.PhotoExhibitionService; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController
@RequestMapping("/api/admin/events/{eventId}/photo-exhibition")
public class PhotoExhibitionAdminController {
private final PhotoExhibitionService service;private final UserRepository users;public PhotoExhibitionAdminController(PhotoExhibitionService s,UserRepository u){service=s;users=u;}private void admin(Authentication a){User u=users.findByEmail(a.getName()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED));if(!"ADMIN".equals(u.getRole()))throw new ResponseStatusException(HttpStatus.FORBIDDEN);}@PatchMapping("/submissions/{submissionId}/exclude") public PhotoExhibitionAdminSubmissionResponse exclude(@PathVariable Long eventId,@PathVariable Long submissionId,@RequestBody(required=false) Map<String,String>b,Authentication a){admin(a);if(b==null||b.get("reason")==null||b.get("reason").isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"제외 사유는 필수입니다.");return PhotoExhibitionAdminSubmissionResponse.from(service.exclude(eventId,submissionId,b.get("reason")));}@PostMapping("/start-voting") @ResponseStatus(HttpStatus.NO_CONTENT) public void startVoting(@PathVariable Long eventId,Authentication a){admin(a);service.startVoting(eventId);}@GetMapping("/submissions") public List<PhotoExhibitionAdminSubmissionResponse> submissions(@PathVariable Long eventId,Authentication a){admin(a);return service.adminList(eventId).stream().map(PhotoExhibitionAdminSubmissionResponse::from).toList();}@GetMapping("/audit-voters") public List<PhotoExhibitionVoterAuditResponse> audit(@PathVariable Long eventId,Authentication a){admin(a);return service.auditVotes(eventId).stream().map(PhotoExhibitionVoterAuditResponse::from).toList();}@GetMapping("/preview") public PhotoExhibitionPreviewResponse preview(@PathVariable Long eventId,Authentication a){admin(a);return service.preview(eventId);}@PostMapping("/finalize") @ResponseStatus(HttpStatus.NO_CONTENT) public void finalize(@PathVariable Long eventId,Authentication a){admin(a);service.finalizeResults(eventId);}}
